"use client"

import * as React from "react"
import { CircleAlertIcon, ContrastIcon, MinusIcon, MoveIcon, PlusIcon, RotateCcwIcon } from "lucide-react"
import { cn } from "@/lib/utils"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Progress } from "@/components/ui/progress"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Slider } from "@/components/ui/slider"
import { Toggle } from "@/components/ui/toggle"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

/**
 * One image of a stack. Pass raw values, such as Hounsfield units, as `data`
 * in row-major order, or an image URL whose luminance (0 to 255) becomes the
 * value. Image URLs must allow CORS so their pixels can be read.
 */
export type ImageSlice =
  | { src: string; label?: string }
  | {
      data: ArrayLike<number>
      width: number
      height: number
      label?: string
    }

/** Display window: values from center - width / 2 to center + width / 2 map to black through white. */
export type ImageWindow = { center: number; width: number }

export type WindowPreset = ImageWindow & { name: string }

/** Common CT windows in Hounsfield units. */
export const ctWindowPresets: readonly WindowPreset[] = [
  { name: "Brain", center: 40, width: 80 },
  { name: "Soft tissue", center: 50, width: 400 },
  { name: "Lung", center: -600, width: 1500 },
  { name: "Bone", center: 400, width: 1800 },
]

export type ImageViewerHandle = {
  setSlice: (index: number) => void
  zoom: (factor: number) => void
  reset: () => void
}

export type ImageViewerTool = "window" | "pan"

export type ImageViewerProps = {
  slices: readonly ImageSlice[]
  /** Zero-based index of the shown slice, when controlled. */
  slice?: number
  defaultSlice?: number
  onSliceChange?: (index: number) => void
  window?: ImageWindow
  /** Defaults to the first preset, or else the first slice's value range. */
  defaultWindow?: ImageWindow
  onWindowChange?: (window: ImageWindow) => void
  /** Named windows offered in the toolbar, such as `ctWindowPresets`. */
  presets?: readonly WindowPreset[]
  /** Physical [row, column] spacing, as in DICOM Pixel Spacing, so pixels keep their true aspect. */
  pixelSpacing?: readonly [number, number]
  /** Unit shown after pixel values, such as "HU". */
  unit?: string
  /** Shows the toolbar and slice slider. Defaults to true. */
  controls?: boolean
  label?: string
  className?: string
  ref?: React.Ref<ImageViewerHandle>
}

/**
 * Maps a value to a gray level from 0 to 255 with the DICOM linear window
 * function (PS3.3 C.11.2.1.2).
 */
export function windowLevel(value: number, { center, width }: ImageWindow) {
  const w = Math.max(width, 1)
  const low = center - 0.5 - (w - 1) / 2
  if (value <= low) return 0
  if (value > center - 0.5 + (w - 1) / 2) return 255
  return ((value - (center - 0.5)) / (w - 1) + 0.5) * 255
}

type Pixels = {
  values: ArrayLike<number>
  width: number
  height: number
  min: number
  max: number
}

function range(values: ArrayLike<number>) {
  let min = Infinity
  let max = -Infinity
  for (let i = 0; i < values.length; i++) {
    const value = values[i]!
    if (value < min) min = value
    if (value > max) max = value
  }
  return { min, max }
}

async function decode(slice: ImageSlice): Promise<Pixels> {
  if ("data" in slice) {
    const { data, width, height } = slice
    if (data.length !== width * height)
      throw new Error(
        `Slice data has ${data.length} values for a ${width} × ${height} image.`
      )
    return { values: data, width, height, ...range(data) }
  }
  const image = new Image()
  image.crossOrigin = "anonymous"
  image.src = slice.src
  try {
    await image.decode()
  } catch {
    throw new Error(`The image at ${slice.src} could not be loaded.`)
  }
  const { naturalWidth: width, naturalHeight: height } = image
  const canvas = document.createElement("canvas")
  canvas.width = width
  canvas.height = height
  const context = canvas.getContext("2d", { willReadFrequently: true })
  if (!context) throw new Error("Canvas is unavailable in this browser.")
  context.drawImage(image, 0, 0)
  const rgba = context.getImageData(0, 0, width, height).data
  const values = new Uint8Array(width * height)
  for (let i = 0; i < values.length; i++)
    values[i] = Math.round(
      0.299 * rgba[i * 4]! + 0.587 * rgba[i * 4 + 1]! + 0.114 * rgba[i * 4 + 2]!
    )
  return { values, width, height, ...range(values) }
}

const MIN_ZOOM = 0.5
const MAX_ZOOM = 16
// Slices ahead and behind the shown one to decode in the background.
const PRELOAD = 3

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max)
}

function formatValue(value: number) {
  return Math.abs(value) >= 10 || Number.isInteger(value)
    ? String(Math.round(value))
    : value.toFixed(2)
}

function ToolbarButton({
  label,
  onClick,
  children,
}: {
  label: string
  onClick: () => void
  children: React.ReactNode
}) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
            variant="ghost"
            size="icon"
            aria-label={label}
            onClick={onClick}
        >
          {children}
        </Button>
      </TooltipTrigger>
      <TooltipContent side="bottom">{label}</TooltipContent>
    </Tooltip>
  )
}

function ToolToggle({
  label,
  pressed,
  onPressedChange,
  children,
}: {
  label: string
  pressed: boolean
  onPressedChange: () => void
  children: React.ReactNode
}) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Toggle
          aria-label={label}
          pressed={pressed}
          onPressedChange={onPressedChange}
        >
          {children}
        </Toggle>
      </TooltipTrigger>
      <TooltipContent side="bottom">{label}</TooltipContent>
    </Tooltip>
  )
}

export function ImageViewer({
  slices,
  slice: sliceProp,
  defaultSlice = 0,
  onSliceChange,
  window: windowProp,
  defaultWindow,
  onWindowChange,
  presets = [],
  pixelSpacing,
  unit,
  controls = true,
  label = "Medical image",
  className,
  ref,
}: ImageViewerProps) {
  const stage = React.useRef<HTMLDivElement>(null)
  const canvas = React.useRef<HTMLCanvasElement>(null)
  const instructions = React.useId()
  const sliceLabel = React.useId()
  const count = slices.length

  const [ownSlice, setOwnSlice] = React.useState(defaultSlice)
  const index = clamp(
    Math.round(sliceProp ?? ownSlice),
    0,
    Math.max(count - 1, 0)
  )
  const changeSlice = React.useCallback(
    (next: number) => {
      const target = clamp(Math.round(next), 0, Math.max(count - 1, 0))
      setOwnSlice(target)
      if (target !== index) onSliceChange?.(target)
    },
    [count, index, onSliceChange]
  )

  // Decoded slices, keyed by the slice objects themselves so new data reloads.
  const cache = React.useRef(new WeakMap<ImageSlice, Promise<Pixels>>())
  const load = React.useCallback((slice: ImageSlice) => {
    let pending = cache.current.get(slice)
    if (!pending) {
      pending = decode(slice)
      pending.catch(() => cache.current.delete(slice))
      cache.current.set(slice, pending)
    }
    return pending
  }, [])
  const [pixels, setPixels] = React.useState<Pixels | null>(null)
  const [attempt, setAttempt] = React.useState(0)
  const [failure, setFailure] = React.useState<{
    slice: ImageSlice
    attempt: number
    message: string
  } | null>(null)
  const [autoWindow, setAutoWindow] = React.useState<ImageWindow | null>(null)
  const current = slices[index]
  const error =
    failure && failure.slice === current && failure.attempt === attempt
      ? failure.message
      : null
  React.useEffect(() => {
    if (!current) return
    let active = true
    load(current).then(
      (result) => {
        if (!active) return
        setPixels(result)
        // Without a window or presets, show the first slice's full range.
        setAutoWindow(
          (previous) =>
            previous ?? {
              center: (result.min + result.max) / 2,
              width: Math.max(result.max - result.min, 1),
            }
        )
        for (let offset = 1; offset <= PRELOAD; offset++)
          for (const neighbour of [
            slices[index + offset],
            slices[index - offset],
          ])
            if (neighbour) load(neighbour).catch(() => {})
      },
      (reason: unknown) => {
        if (active)
          setFailure({
            slice: current,
            attempt,
            message: reason instanceof Error ? reason.message : String(reason),
          })
      }
    )
    return () => {
      active = false
    }
  }, [current, slices, index, load, attempt])

  const [ownWindow, setOwnWindow] = React.useState<ImageWindow | null>(
    defaultWindow ?? presets[0] ?? null
  )
  const shownWindow = windowProp ?? ownWindow ?? autoWindow
  const changeWindow = React.useCallback(
    (next: ImageWindow) => {
      const value = { center: next.center, width: Math.max(next.width, 1) }
      setOwnWindow(value)
      onWindowChange?.(value)
    },
    [onWindowChange]
  )
  const preset =
    presets.find(
      ({ center, width }) =>
        shownWindow &&
        Math.abs(center - shownWindow.center) < 1e-6 &&
        Math.abs(width - shownWindow.width) < 1e-6
    )?.name ?? null

  const [view, setView] = React.useState({ zoom: 1, x: 0, y: 0 })
  const [size, setSize] = React.useState({ width: 0, height: 0 })
  const [tool, setTool] = React.useState<ImageViewerTool>("window")
  const [hover, setHover] = React.useState<{
    x: number
    y: number
    value: number
  } | null>(null)
  const [interacted, setInteracted] = React.useState(false)

  React.useEffect(() => {
    const element = stage.current
    if (!element) return
    const observer = new ResizeObserver(([entry]) => {
      if (entry)
        setSize({
          width: entry.contentRect.width,
          height: entry.contentRect.height,
        })
    })
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  // Physical size of a pixel relative to the smaller spacing.
  const [rowSpacing, columnSpacing] = pixelSpacing ?? [1, 1]
  const unitSpacing = Math.min(rowSpacing, columnSpacing)
  const scaleX = columnSpacing / unitSpacing
  const scaleY = rowSpacing / unitSpacing
  const fit = pixels
    ? Math.min(
        size.width / (pixels.width * scaleX),
        size.height / (pixels.height * scaleY)
      )
    : 1

  // The windowed slice, rendered once per slice or window change.
  const bitmap = React.useMemo(() => {
    if (!pixels || !shownWindow || typeof document === "undefined") return null
    const { values, width, height } = pixels
    const element = document.createElement("canvas")
    element.width = width
    element.height = height
    const context = element.getContext("2d")
    if (!context) return null
    const image = context.createImageData(width, height)
    for (let i = 0; i < values.length; i++) {
      const gray = windowLevel(values[i]!, shownWindow)
      image.data[i * 4] = gray
      image.data[i * 4 + 1] = gray
      image.data[i * 4 + 2] = gray
      image.data[i * 4 + 3] = 255
    }
    context.putImageData(image, 0, 0)
    return element
  }, [pixels, shownWindow])

  React.useLayoutEffect(() => {
    const element = canvas.current
    if (!element) return
    const ratio = globalThis.devicePixelRatio || 1
    element.width = Math.round(size.width * ratio)
    element.height = Math.round(size.height * ratio)
    const context = element.getContext("2d")
    if (!context) return
    context.setTransform(1, 0, 0, 1, 0, 0)
    // Radiology convention: images sit on true black (ui-system exception).
    context.fillStyle = "#000"
    context.fillRect(0, 0, element.width, element.height)
    if (!bitmap) return
    const scale = fit * view.zoom
    context.setTransform(
      ratio * scale * scaleX,
      0,
      0,
      ratio * scale * scaleY,
      ratio * (size.width / 2 + view.x),
      ratio * (size.height / 2 + view.y)
    )
    // Show individual pixels once they are large enough to inspect.
    context.imageSmoothingEnabled = scale * Math.min(scaleX, scaleY) < 8
    context.drawImage(bitmap, -bitmap.width / 2, -bitmap.height / 2)
  }, [bitmap, size, fit, view, scaleX, scaleY])

  // Image pixel under a point relative to the stage's top-left corner.
  const pixelAt = (x: number, y: number) => {
    if (!pixels) return null
    const scale = fit * view.zoom
    const column = Math.floor(
      (x - size.width / 2 - view.x) / (scale * scaleX) + pixels.width / 2
    )
    const row = Math.floor(
      (y - size.height / 2 - view.y) / (scale * scaleY) + pixels.height / 2
    )
    if (column < 0 || row < 0 || column >= pixels.width || row >= pixels.height)
      return null
    return {
      x: column,
      y: row,
      value: pixels.values[row * pixels.width + column]!,
    }
  }

  const zoomAt = React.useCallback(
    (factor: number, x = 0, y = 0) =>
      setView((previous) => {
        const zoom = clamp(previous.zoom * factor, MIN_ZOOM, MAX_ZOOM)
        const ratio = zoom / previous.zoom
        return {
          zoom,
          x: x - (x - previous.x) * ratio,
          y: y - (y - previous.y) * ratio,
        }
      }),
    []
  )
  const reset = React.useCallback(() => setView({ zoom: 1, x: 0, y: 0 }), [])

  // Wheel scrolls slices; a pinch or ctrl + wheel zooms at the pointer. React
  // wheel listeners are passive, so this one is added directly.
  const wheel = React.useRef({ changeSlice, index, zoomAt, delta: 0 })
  React.useEffect(() => {
    Object.assign(wheel.current, { changeSlice, index, zoomAt })
  }, [changeSlice, index, zoomAt])
  React.useEffect(() => {
    const element = stage.current
    if (!element) return
    const onWheel = (event: WheelEvent) => {
      event.preventDefault()
      setInteracted(true)
      const state = wheel.current
      const pixels =
        event.deltaMode === WheelEvent.DOM_DELTA_LINE
          ? event.deltaY * 40
          : event.deltaY
      if (event.ctrlKey || event.metaKey) {
        const box = element.getBoundingClientRect()
        state.zoomAt(
          Math.exp(-pixels / 200),
          event.clientX - box.left - box.width / 2,
          event.clientY - box.top - box.height / 2
        )
        return
      }
      state.delta += pixels
      const steps = Math.trunc(state.delta / 40)
      if (steps) {
        state.delta -= steps * 40
        state.changeSlice(state.index + steps)
      }
    }
    element.addEventListener("wheel", onWheel, { passive: false })
    return () => element.removeEventListener("wheel", onWheel)
  }, [])

  const pointers = React.useRef(new Map<number, { x: number; y: number }>())
  const drag = React.useRef<{
    mode: ImageViewerTool | "pinch"
    window: ImageWindow | null
    distance: number
  } | null>(null)

  const local = (event: React.PointerEvent) => {
    const box = event.currentTarget.getBoundingClientRect()
    return { x: event.clientX - box.left, y: event.clientY - box.top }
  }

  const onPointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    // Only the image itself drags; the toolbar and messages keep their own
    // pointer handling.
    if (
      !pixels ||
      event.target !== canvas.current ||
      (event.pointerType === "mouse" && event.button > 1)
    )
      return
    event.currentTarget.setPointerCapture(event.pointerId)
    pointers.current.set(event.pointerId, local(event))
    setInteracted(true)
    setHover(null)
    const points = [...pointers.current.values()]
    if (points.length === 2) {
      drag.current = {
        mode: "pinch",
        window: null,
        distance: Math.hypot(
          points[0]!.x - points[1]!.x,
          points[0]!.y - points[1]!.y
        ),
      }
      return
    }
    drag.current = {
      mode:
        event.button === 1 || event.shiftKey || tool === "pan"
          ? "pan"
          : "window",
      window: shownWindow,
      distance: 0,
    }
  }

  const onPointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    const point = local(event)
    const previous = pointers.current.get(event.pointerId)
    if (!previous || !drag.current) {
      if (event.pointerType === "mouse") setHover(pixelAt(point.x, point.y))
      return
    }
    pointers.current.set(event.pointerId, point)
    const dx = point.x - previous.x
    const dy = point.y - previous.y
    const state = drag.current
    if (state.mode === "pinch") {
      const points = [...pointers.current.values()]
      if (points.length < 2) return
      const distance = Math.hypot(
        points[0]!.x - points[1]!.x,
        points[0]!.y - points[1]!.y
      )
      if (state.distance > 0)
        zoomAt(
          distance / state.distance,
          (points[0]!.x + points[1]!.x) / 2 - size.width / 2,
          (points[0]!.y + points[1]!.y) / 2 - size.height / 2
        )
      state.distance = distance
    } else if (state.mode === "pan") {
      setView((view) => ({ ...view, x: view.x + dx, y: view.y + dy }))
    } else if (state.window) {
      // Right widens the window and down raises the level, in proportion to
      // the current width so narrow and wide windows both feel responsive.
      const step = Math.max(state.window.width, 1) / 200
      state.window = {
        center: state.window.center + dy * step,
        width: state.window.width * Math.exp(dx / 200),
      }
      changeWindow(state.window)
    }
  }

  const onPointerUp = (event: React.PointerEvent<HTMLDivElement>) => {
    pointers.current.delete(event.pointerId)
    if (pointers.current.size === 0) drag.current = null
    else if (drag.current?.mode === "pinch")
      drag.current = { mode: "pan", window: null, distance: 0 }
  }

  React.useImperativeHandle(
    ref,
    () => ({ setSlice: changeSlice, zoom: (factor) => zoomAt(factor), reset }),
    [changeSlice, zoomAt, reset]
  )

  const message =
    count === 0
      ? { title: "No images", text: "This series has no slices to show." }
      : error
        ? {
            title: "The image couldn’t load",
            text: `${error} Check your connection and try again.`,
          }
        : null
  const unitText = unit ? ` ${unit}` : ""
  const name = current?.label

  return (
    <div
      className={cn(
        "flex h-[28rem] w-full flex-col overflow-hidden rounded-xl border bg-background text-sm text-foreground",
        className
      )}
    >
      <div
        ref={stage}
        role="region"
        aria-label={label}
        aria-describedby={instructions}
        tabIndex={0}
        className="relative min-h-0 flex-1 touch-none overflow-hidden bg-black select-none focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring"
        style={{
          cursor: !pixels ? undefined : tool === "pan" ? "grab" : "crosshair",
        }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onPointerLeave={() => setHover(null)}
        onKeyDown={(event) => {
          if (event.target !== event.currentTarget) return
          const actions: Record<string, () => void> = {
            ArrowUp: () => changeSlice(index - 1),
            ArrowDown: () => changeSlice(index + 1),
            PageUp: () => changeSlice(index - 10),
            PageDown: () => changeSlice(index + 10),
            Home: () => changeSlice(0),
            End: () => changeSlice(count - 1),
            "+": () => zoomAt(1.25),
            "=": () => zoomAt(1.25),
            "-": () => zoomAt(0.8),
            "0": reset,
          }
          const action = actions[event.key]
          if (!action) return
          event.preventDefault()
          setInteracted(true)
          action()
        }}
      >
        <p id={instructions} className="sr-only">
          Use the up and down arrow keys or scroll to move through slices, and
          plus, minus and zero to zoom and reset. Drag to adjust the window, or
          to pan when the pan tool is on.
        </p>
        <canvas
          ref={canvas}
          role="img"
          aria-label={
            count
              ? `${label}, slice ${index + 1} of ${count}${name ? `, ${name}` : ""}`
              : label
          }
          className="absolute inset-0 size-full"
        />
        {message ? (
          <div className="absolute inset-0 flex items-center justify-center p-6">
            <Alert className="max-w-sm">
              <CircleAlertIcon
                aria-hidden="true"
              />
              <AlertTitle>{message.title}</AlertTitle>
              <AlertDescription>
                <p>{message.text}</p>
                {error && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setAttempt((n) => n + 1)}
                    className="mt-3 text-foreground"
                  >
                    Try again
                  </Button>
                )}
              </AlertDescription>
            </Alert>
          </div>
        ) : !pixels ? (
          <div
            role="status"
            className="absolute inset-0 flex flex-col items-center justify-center gap-3 p-6 text-background dark:text-foreground"
          >
            <Progress
              value={null}
              aria-label="Loading image"
              className="w-40"
            />
            <p>Loading image</p>
          </div>
        ) : null}
        {pixels && (
          <>
            <div
              aria-hidden="true"
              className="pointer-events-none absolute bottom-2 left-3 flex flex-col text-xs rounded bg-background/80 px-1.5 text-foreground tabular-nums"
            >
              <span>
                {name ? `${name} · ` : ""}
                {index + 1} / {count}
              </span>
              {hover && (
                <span>
                  {hover.x}, {hover.y} · {formatValue(hover.value)}
                  {unitText}
                </span>
              )}
              {shownWindow && (
                <span>
                  W {formatValue(shownWindow.width)} · L{" "}
                  {formatValue(shownWindow.center)}
                </span>
              )}
            </div>
            <span
              aria-hidden="true"
              className="pointer-events-none absolute right-3 bottom-2 text-xs rounded bg-background/80 px-1.5 text-foreground tabular-nums"
            >
              {Math.round(view.zoom * 100)}%
            </span>
            {!interacted && (
              <p
                aria-hidden="true"
                className="pointer-events-none absolute inset-x-0 bottom-16 hidden text-center text-xs rounded bg-background/80 px-1.5 text-foreground tabular-nums sm:block"
              >
                Scroll for slices · Drag to window · Ctrl + scroll to zoom
              </p>
            )}
          </>
        )}
        {pixels && controls && (
          <TooltipProvider>
            <div
              role="toolbar"
              aria-label="Image controls"
              className="absolute top-2 right-2 flex max-w-[calc(100%-1rem)] flex-wrap items-center justify-end gap-0.5 rounded-lg border bg-background/90 p-1 shadow-sm backdrop-blur"
            >
              {presets.length > 0 && (
                <Select
                  value={preset ?? ""}
                  onValueChange={(next) => {
                    const match = presets.find(({ name }) => name === next)
                    if (match)
                      changeWindow({ center: match.center, width: match.width })
                  }}
                >
                  <SelectTrigger
                    aria-label="Window preset"
                    className="border-transparent"
                  >
                    <SelectValue placeholder="Custom" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      {presets.map(({ name }) => (
                        <SelectItem key={name} value={name}>
                          {name}
                        </SelectItem>
                      ))}
                    </SelectGroup>
                  </SelectContent>
                </Select>
              )}
              <ToolToggle
                label="Window tool"
                pressed={tool === "window"}
                onPressedChange={() => setTool("window")}
              >
                <ContrastIcon
                  aria-hidden="true"
                />
              </ToolToggle>
              <ToolToggle
                label="Pan tool"
                pressed={tool === "pan"}
                onPressedChange={() => setTool("pan")}
              >
                <MoveIcon
                  aria-hidden="true"
                />
              </ToolToggle>
              <ToolbarButton label="Zoom in" onClick={() => zoomAt(1.25)}>
                <PlusIcon
                  aria-hidden="true"
                />
              </ToolbarButton>
              <ToolbarButton label="Zoom out" onClick={() => zoomAt(0.8)}>
                <MinusIcon
                  aria-hidden="true"
                />
              </ToolbarButton>
              <ToolbarButton label="Reset view" onClick={reset}>
                <RotateCcwIcon
                  aria-hidden="true"
                />
              </ToolbarButton>
            </div>
          </TooltipProvider>
        )}
      </div>
      {controls && count > 1 && (
        <div className="flex items-center gap-3 border-t px-3 py-2.5">
          <span id={sliceLabel} className="text-xs font-medium">
            Slice
          </span>
          <Slider
            aria-labelledby={sliceLabel}
            min={1}
            max={count}
            // An array, so shadcn's slider renders a single thumb.
            value={[index + 1]}
            onValueChange={(next) =>
              changeSlice((Array.isArray(next) ? next[0]! : next) - 1)
            }
            className="flex-1"
          />
          <span className="min-w-14 text-right text-xs text-muted-foreground tabular-nums">
            {index + 1} / {count}
          </span>
        </div>
      )}
    </div>
  )
}

/**
 * Theme tokens for clinical and anatomy pieces.
 *
 * OrganUI ships fixed anatomical colours. Retana UI items inherit the host
 * theme instead, so every structure, trace and fill names a token and an
 * optional lightness shade. SVG and CSS use the token directly; WebGL reads
 * the resolved token once per theme change.
 */
export type ClinicalTone =
  | "chart-1"
  | "chart-2"
  | "chart-3"
  | "chart-4"
  | "chart-5"
  | "primary"
  | "destructive"
  | "muted-foreground"
  | "foreground"

export const CLINICAL_TONES: readonly ClinicalTone[] = [
  "chart-1",
  "chart-2",
  "chart-3",
  "chart-4",
  "chart-5",
]

/** CSS value for a tone. shade -1..1 mixes toward background (+) or foreground (-). */
export function toneVar(tone: ClinicalTone, shade = 0) {
  if (!shade) return `var(--${tone})`
  const pct = Math.round(Math.min(Math.abs(shade), 1) * 100)
  return shade > 0
    ? `color-mix(in oklch, var(--${tone}), var(--background) ${pct}%)`
    : `color-mix(in oklch, var(--${tone}), var(--foreground) ${pct}%)`
}

/** A tone picked by position, for series without a fixed meaning. */
export function toneAt(index: number): ClinicalTone {
  return CLINICAL_TONES[((index % CLINICAL_TONES.length) + CLINICAL_TONES.length) % CLINICAL_TONES.length]!
}

export type Rgb = readonly [number, number, number]

const cache = new Map<string, Rgb>()
let probe: CanvasRenderingContext2D | null | undefined

/**
 * Resolve any CSS colour expression (tokens, color-mix) to sRGB 0..1 by
 * painting one pixel. Returns null outside the browser.
 */
export function resolveCssColor(value: string, scope?: Element | null): Rgb | null {
  if (typeof document === "undefined") return null
  const key = value
  const hit = cache.get(key)
  if (hit) return hit
  const host = document.createElement("span")
  host.style.color = value
  host.style.display = "none"
  ;(scope ?? document.body).appendChild(host)
  const computed = getComputedStyle(host).color
  host.remove()
  if (probe === undefined) {
    const canvas = document.createElement("canvas")
    canvas.width = canvas.height = 1
    probe = canvas.getContext("2d", { willReadFrequently: true })
  }
  if (!probe || !computed) return null
  probe.clearRect(0, 0, 1, 1)
  probe.fillStyle = computed
  probe.fillRect(0, 0, 1, 1)
  const [r, g, b] = probe.getImageData(0, 0, 1, 1).data
  const rgb: Rgb = [r! / 255, g! / 255, b! / 255]
  cache.set(key, rgb)
  return rgb
}

/** Drop resolved colours, for example after the host switches theme. */
export function clearToneCache() {
  cache.clear()
}

/** Call back when the document theme class or style changes. */
export function onThemeChange(callback: () => void) {
  if (typeof MutationObserver === "undefined" || typeof document === "undefined") return () => {}
  const observer = new MutationObserver(() => {
    clearToneCache()
    callback()
  })
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style", "data-theme"] })
  return () => observer.disconnect()
}

// A small reader for uncompressed, single-frame grayscale DICOM files, such
// as most CT and MR series. It is not a validated medical device and reads
// only what the image viewer needs.

export type DicomImage = {
  /** Modality values (Hounsfield units for CT): stored values after rescale slope and intercept. */
  data: Float32Array
  width: number
  height: number
  /** [row, column] spacing in millimetres, from Pixel Spacing. */
  pixelSpacing?: [number, number]
  /** The first Window Center and Width stored in the file. */
  window?: { center: number; width: number }
  /** Image Position (Patient), Slice Location and Instance Number, used to order a series. */
  position?: [number, number, number]
  sliceLocation?: number
  instanceNumber?: number
  modality?: string
  label?: string
}

const IMPLICIT_LITTLE = "1.2.840.10008.1.2"
const EXPLICIT_LITTLE = "1.2.840.10008.1.2.1"
// Explicit VRs with a reserved two bytes and a four-byte length.
const LONG_VRS = new Set([
  "OB",
  "OD",
  "OF",
  "OL",
  "OV",
  "OW",
  "SQ",
  "SV",
  "UC",
  "UN",
  "UR",
  "UT",
  "UV",
])
const UNDEFINED = 0xffffffff
const ITEM = 0xfffee000
const ITEM_END = 0xfffee00d
const SEQUENCE_END = 0xfffee0dd

const tag = (group: number, element: number) => ((group << 16) | element) >>> 0

const TAGS = {
  modality: tag(0x0008, 0x0060),
  seriesDescription: tag(0x0008, 0x103e),
  instanceNumber: tag(0x0020, 0x0013),
  position: tag(0x0020, 0x0032),
  sliceLocation: tag(0x0020, 0x1041),
  samplesPerPixel: tag(0x0028, 0x0002),
  photometric: tag(0x0028, 0x0004),
  frames: tag(0x0028, 0x0008),
  rows: tag(0x0028, 0x0010),
  columns: tag(0x0028, 0x0011),
  pixelSpacing: tag(0x0028, 0x0030),
  bitsAllocated: tag(0x0028, 0x0100),
  bitsStored: tag(0x0028, 0x0101),
  pixelRepresentation: tag(0x0028, 0x0103),
  windowCenter: tag(0x0028, 0x1050),
  windowWidth: tag(0x0028, 0x1051),
  intercept: tag(0x0028, 0x1052),
  slope: tag(0x0028, 0x1053),
  pixelData: tag(0x7fe0, 0x0010),
}

type Element = { offset: number; length: number }

function parseElements(view: DataView, start: number, explicit: boolean) {
  const elements = new Map<number, Element>()
  const text = (offset: number) =>
    String.fromCharCode(view.getUint8(offset), view.getUint8(offset + 1))

  // Returns the offset after the element at `offset`, recording top-level ones.
  const read = (offset: number, record: boolean) => {
    const id = tag(
      view.getUint16(offset, true),
      view.getUint16(offset + 2, true)
    )
    let length: number
    let vr: string | null = null
    let cursor = offset + 4
    if (id === ITEM || id === ITEM_END || id === SEQUENCE_END) {
      length = view.getUint32(cursor, true)
      cursor += 4
    } else if (explicit) {
      vr = text(cursor)
      if (LONG_VRS.has(vr)) {
        length = view.getUint32(cursor + 4, true)
        cursor += 8
      } else {
        length = view.getUint16(cursor + 2, true)
        cursor += 4
      }
    } else {
      length = view.getUint32(cursor, true)
      cursor += 4
    }
    if (length === UNDEFINED) {
      if (id === tag(0x7fe0, 0x0010))
        throw new Error(
          "Compressed (encapsulated) pixel data is not supported."
        )
      cursor = skipUndefined(cursor)
      return cursor
    }
    if (record) elements.set(id, { offset: cursor, length })
    return cursor + length
  }

  // Skips an undefined-length sequence or item up to its delimiter.
  const skipUndefined = (offset: number): number => {
    let cursor = offset
    while (cursor + 8 <= view.byteLength) {
      const id = tag(
        view.getUint16(cursor, true),
        view.getUint16(cursor + 2, true)
      )
      if (id === SEQUENCE_END || id === ITEM_END) return cursor + 8
      if (id === ITEM) {
        const length = view.getUint32(cursor + 4, true)
        cursor =
          length === UNDEFINED ? skipUndefined(cursor + 8) : cursor + 8 + length
        continue
      }
      cursor = read(cursor, false)
    }
    throw new Error("The file ends inside a sequence.")
  }

  let cursor = start
  while (cursor + 8 <= view.byteLength) {
    cursor = read(cursor, true)
  }
  return elements
}

/** Reads one DICOM file (Part 10, with its 128-byte preamble) into raw values. */
export function parseDicom(buffer: ArrayBuffer): DicomImage {
  const view = new DataView(buffer)
  const bytes = new Uint8Array(buffer)
  const magic = String.fromCharCode(...bytes.subarray(128, 132))
  if (magic !== "DICM") throw new Error("This is not a DICOM Part 10 file.")

  const decoder = new TextDecoder("latin1")
  const decode = (offset: number, length: number) =>
    decoder
      .decode(bytes.subarray(offset, offset + length))
      .replace(/[\0\s]+$/, "")
      .trim()
  // The meta group (0002) is always explicit little endian and states the
  // transfer syntax of the dataset after it.
  let syntax = EXPLICIT_LITTLE
  let start = 132
  while (start + 8 <= view.byteLength && view.getUint16(start, true) === 2) {
    const vr = String.fromCharCode(bytes[start + 4]!, bytes[start + 5]!)
    const long = LONG_VRS.has(vr)
    const length = long
      ? view.getUint32(start + 8, true)
      : view.getUint16(start + 6, true)
    const value = start + (long ? 12 : 8)
    if (view.getUint16(start + 2, true) === 0x0010)
      syntax = decode(value, length)
    start = value + length
  }
  if (syntax !== IMPLICIT_LITTLE && syntax !== EXPLICIT_LITTLE)
    throw new Error(
      `Transfer syntax ${syntax} is not supported. Only uncompressed little endian files can be read.`
    )
  const elements = parseElements(view, start, syntax === EXPLICIT_LITTLE)

  const string = (id: number) => {
    const element = elements.get(id)
    return element ? decode(element.offset, element.length) : undefined
  }
  const uint16 = (id: number) => {
    const element = elements.get(id)
    return element ? view.getUint16(element.offset, true) : undefined
  }
  const numbers = (id: number) =>
    string(id)
      ?.split("\\")
      .map(Number)
      .filter((value) => Number.isFinite(value))

  const width = uint16(TAGS.columns)
  const height = uint16(TAGS.rows)
  const bitsAllocated = uint16(TAGS.bitsAllocated) ?? 16
  const signed = uint16(TAGS.pixelRepresentation) === 1
  const pixelData = elements.get(TAGS.pixelData)
  if (!width || !height || !pixelData) throw new Error("The file has no image.")
  if ((uint16(TAGS.samplesPerPixel) ?? 1) !== 1)
    throw new Error("Only grayscale images are supported.")
  if (Number(string(TAGS.frames) ?? 1) > 1)
    throw new Error("Multi-frame images are not supported.")
  if (bitsAllocated !== 8 && bitsAllocated !== 16)
    throw new Error(`${bitsAllocated}-bit pixels are not supported.`)

  const count = width * height
  if (pixelData.length < count * (bitsAllocated / 8))
    throw new Error("The pixel data is shorter than the image.")
  const bitsStored = uint16(TAGS.bitsStored) ?? bitsAllocated
  const slope = numbers(TAGS.slope)?.[0] ?? 1
  const intercept = numbers(TAGS.intercept)?.[0] ?? 0
  const photometric = string(TAGS.photometric) ?? "MONOCHROME2"
  if (photometric !== "MONOCHROME1" && photometric !== "MONOCHROME2")
    throw new Error(`${photometric} images are not supported.`)
  // MONOCHROME1 shows low values as white; negate so the viewer's black-to-
  // white window keeps the same appearance.
  const sign = photometric === "MONOCHROME1" ? -1 : 1
  const data = new Float32Array(count)
  const shift = 32 - bitsStored
  for (let i = 0; i < count; i++) {
    let stored =
      bitsAllocated === 8
        ? bytes[pixelData.offset + i]!
        : view.getUint16(pixelData.offset + i * 2, true)
    // Keep only the stored bits, sign-extending when they are signed.
    stored = signed ? (stored << shift) >> shift : (stored << shift) >>> shift
    data[i] = sign * (stored * slope + intercept)
  }

  const image: DicomImage = { data, width, height }
  const spacing = numbers(TAGS.pixelSpacing)
  if (spacing?.length === 2) image.pixelSpacing = [spacing[0]!, spacing[1]!]
  const center = numbers(TAGS.windowCenter)?.[0]
  const windowWidth = numbers(TAGS.windowWidth)?.[0]
  if (center !== undefined && windowWidth !== undefined)
    image.window = { center: sign * center, width: windowWidth }
  const position = numbers(TAGS.position)
  if (position?.length === 3)
    image.position = [position[0]!, position[1]!, position[2]!]
  const location = numbers(TAGS.sliceLocation)?.[0]
  if (location !== undefined) image.sliceLocation = location
  const instance = numbers(TAGS.instanceNumber)?.[0]
  if (instance !== undefined) image.instanceNumber = instance
  const modality = string(TAGS.modality)
  if (modality) image.modality = modality
  const description = string(TAGS.seriesDescription)
  if (description) image.label = description
  return image
}

/**
 * Orders the images of one series from head to foot (or by Slice Location,
 * then Instance Number) and returns props for the image viewer.
 */
export function dicomSeries(images: readonly DicomImage[]) {
  const key = (image: DicomImage) =>
    image.position
      ? -image.position[2]
      : image.sliceLocation !== undefined
        ? -image.sliceLocation
        : (image.instanceNumber ?? 0)
  const slices = [...images].sort((a, b) => key(a) - key(b))
  const first = slices[0]
  return {
    slices,
    pixelSpacing: first?.pixelSpacing,
    window: first?.window,
    unit: first?.modality === "CT" ? "HU" : undefined,
  }
}

// A synthetic head CT for trying the image viewer without patient data: the
// 3D Shepp–Logan phantom (Kak and Slaney, Principles of Computerized
// Tomographic Imaging, 1988), with each ellipsoid given an approximate
// Hounsfield value. It is generated, so it carries no licence terms or
// patient information.

type Ellipsoid = {
  /** Semi-axes, centre and rotation about the vertical axis in degrees, in a -1 to 1 cube. */
  axes: [number, number, number]
  center: [number, number, number]
  angle: number
  /** Added to the value of everything inside, in Hounsfield units. */
  value: number
}

const ELLIPSOIDS: readonly Ellipsoid[] = [
  // Skull, then the brain inside it.
  { axes: [0.69, 0.92, 0.81], center: [0, 0, 0], angle: 0, value: 1800 },
  {
    axes: [0.6624, 0.874, 0.78],
    center: [0, -0.0184, 0],
    angle: 0,
    value: -760,
  },
  // Ventricles.
  { axes: [0.11, 0.31, 0.22], center: [0.22, 0, 0], angle: -18, value: -32 },
  { axes: [0.16, 0.41, 0.28], center: [-0.22, 0, 0], angle: 18, value: -32 },
  // Small lesions.
  { axes: [0.21, 0.25, 0.41], center: [0, 0.35, -0.15], angle: 0, value: 22 },
  { axes: [0.046, 0.046, 0.05], center: [0, 0.1, 0.25], angle: 0, value: 30 },
  { axes: [0.046, 0.046, 0.05], center: [0, -0.1, 0.25], angle: 0, value: 30 },
  {
    axes: [0.046, 0.023, 0.05],
    center: [-0.08, -0.605, 0],
    angle: 0,
    value: 30,
  },
  { axes: [0.023, 0.023, 0.02], center: [0, -0.606, 0], angle: 0, value: 30 },
  {
    axes: [0.023, 0.046, 0.02],
    center: [0.06, -0.605, 0],
    angle: 0,
    value: 30,
  },
]

const AIR = -1000

export type HeadPhantomOptions = {
  /** Pixels per side. Defaults to 128. */
  size?: number
  /** Number of axial slices. Defaults to 32. */
  slices?: number
  /** Standard deviation of the added noise in Hounsfield units. Defaults to 6. */
  noise?: number
}

/**
 * Axial slices of the phantom from the top of the head down, as props for
 * the image viewer: raw values in Hounsfield units and their pixel spacing.
 */
export function createHeadPhantom({
  size = 128,
  slices = 32,
  noise = 6,
}: HeadPhantomOptions = {}) {
  // A fixed seed keeps the noise the same on every render and in tests.
  let seed = 0x2f6b
  const random = () => {
    seed = (seed * 1664525 + 1013904223) >>> 0
    return seed / 2 ** 32
  }
  const gaussian = () =>
    Math.sqrt(-2 * Math.log(1 - random())) * Math.cos(2 * Math.PI * random())
  const shapes = ELLIPSOIDS.map(({ axes, center, angle, value }) => ({
    axes,
    center,
    cos: Math.cos((angle * Math.PI) / 180),
    sin: Math.sin((angle * Math.PI) / 180),
    value,
  }))
  const extent = 0.9
  const result = []
  for (let k = 0; k < slices; k++) {
    // From near the vertex (z = 0.75) to below the skull base (z = -0.75).
    const z = slices === 1 ? 0 : 0.75 - (1.5 * k) / (slices - 1)
    const data = new Int16Array(size * size)
    for (let row = 0; row < size; row++) {
      // Rows run anterior (top of the image) to posterior.
      const y = extent - (2 * extent * (row + 0.5)) / size
      for (let column = 0; column < size; column++) {
        const x = -extent + (2 * extent * (column + 0.5)) / size
        let value = AIR
        for (const shape of shapes) {
          const dx = x - shape.center[0]
          const dy = y - shape.center[1]
          const dz = z - shape.center[2]
          const u = (dx * shape.cos + dy * shape.sin) / shape.axes[0]
          const v = (-dx * shape.sin + dy * shape.cos) / shape.axes[1]
          const w = dz / shape.axes[2]
          if (u * u + v * v + w * w <= 1) value += shape.value
        }
        data[row * size + column] = Math.round(
          value + (value > AIR ? noise * gaussian() : 0)
        )
      }
    }
    result.push({
      data,
      width: size,
      height: size,
      label: `Axial ${k + 1}`,
    })
  }
  // The phantom spans about 240 mm across.
  const spacing = 240 / size
  return {
    slices: result,
    pixelSpacing: [spacing, spacing] as [number, number],
    unit: "HU",
  }
}
